import type { BorrowBookInput, BorrowBookOutput, BorrowBookCaps } from "./contract.js";
import { findBook } from "./find-book/impl.js";
import { checkMember } from "./check-member/impl.js";
import { decideLoan } from "./decide-loan/impl.js";
import { issueLoan } from "./issue-loan/impl.js";
import { writeReceipt } from "./write-receipt/impl.js";

/** Decide whether one member may take one book away, record it, and say what happened. */
export async function borrowBook(input: BorrowBookInput, caps: BorrowBookCaps): Promise<BorrowBookOutput> {
  const { memberId, isbn } = input;

  const { book } = await findBook({ isbn }, caps);

  const { member } = await checkMember({ memberId }, caps);

  const { allowed, dueInDays, reason } = await decideLoan({ book, member }, caps);

  const { copiesLeft } = await issueLoan({ book, member, allowed, dueInDays }, caps);

  const { receipt } = await writeReceipt({ book, allowed, reason, dueInDays, copiesLeft }, caps);

  return { receipt };
}
